INSERT INTO meta.source (source_code, source_name, source_home_url, license_note) VALUES ('IMF_SDMX_PIP_API_V1', 'International Monetary Fund SDMX PIP API', 'https://data.imf.org/', 'IMF public SDMX PIP API') ON CONFLICT (source_code) DO UPDATE SET source_name=EXCLUDED.source_name, source_home_url=EXCLUDED.source_home_url;
INSERT INTO _source_row SELECT source_id FROM meta.source WHERE source_code='IMF_SDMX_PIP_API_V1' LIMIT 1;
INSERT INTO meta.dataset_release (source_id, provider_dataset_code, release_key, release_date, source_url, raw_artifact_path, raw_sha256, metadata) SELECT source_id, 'IMF:PIP', 'imf-pip-asof-20260311t004734566029300z', NULL, 'https://api.imf.org/external/sdmx/2.1/dataflow/all/PIP/latest?references=all', 'data/processed/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-manifest.json', '8eb66d66dcc4b7613f251b77ab1291ca5821563407ebea170e4117caa6061a13', '{"candidate_cell_count": 8640, "explicit_missing_value_count": 275, "observed_value_count": 8000, "release_as_of_date": "2026-03-11", "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-218", "whole_series_absence_count": 73}'::jsonb FROM _source_row ON CONFLICT (source_id, provider_dataset_code, release_key) DO UPDATE SET source_url=EXCLUDED.source_url, raw_artifact_path=EXCLUDED.raw_artifact_path, raw_sha256=EXCLUDED.raw_sha256, metadata=EXCLUDED.metadata;
INSERT INTO _release_row SELECT dr.dataset_release_id FROM meta.dataset_release dr JOIN _source_row s ON dr.source_id=s.source_id WHERE provider_dataset_code='IMF:PIP' AND release_key='imf-pip-asof-20260311t004734566029300z' LIMIT 1;
INSERT INTO meta.pipeline_run (run_key, source_id, dataset_release_id, pipeline_name, finished_at, status, input_parameters, artifact_manifest) SELECT 'task-218-imf-pip-portfolio-counterpart-phase2', s.source_id, r.dataset_release_id, 'imf_pip_portfolio_counterpart_phase2_campaign', now(), 'succeeded', '{"counterpart_dimension": "COUNTERPART_COUNTRY", "endPeriod": "2024", "indicators": ["P_TOTINV_P_USD", "P_F51_P_USD", "P_F3_P_USD"], "selected_economies": ["AUS", "BEL", "BRA", "CAN", "CHE", "CHN", "DEU", "ESP", "FRA", "GBR", "HKG", "IND", "IRL", "ITA", "JPN", "KOR", "LUX", "MEX", "NLD", "NOR", "SGP", "SWE", "USA", "DNK"], "startPeriod": "2020", "task": "TASK-218"}'::jsonb, '{"manifest_path": "data/processed/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-manifest.json", "normalized_path": "data/processed/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-normalized.json", "raw_paths": ["data/raw/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-values-chunk-01.xml", "data/raw/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-values-chunk-02.xml", "data/raw/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-values-chunk-03.xml", "data/raw/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-values-chunk-04.xml"]}'::jsonb FROM _source_row s CROSS JOIN _release_row r ON CONFLICT (run_key) DO UPDATE SET finished_at=EXCLUDED.finished_at, status=EXCLUDED.status, input_parameters=EXCLUDED.input_parameters, artifact_manifest=EXCLUDED.artifact_manifest;
INSERT INTO _run_row SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-218-imf-pip-portfolio-counterpart-phase2' LIMIT 1;
INSERT INTO staging.task218_imf_pip_portfolio_counterpart_observation (pipeline_run_id, source_id, dataset_release_id, territory_code, territory_label, indicator_code, indicator_name, provider_period_code, period_year, value, unit_code, unit_label, decimal_precision, observation_status, attribute_hash, attributes, source_payload) SELECT _run_row.pipeline_run_id, _source_row.source_id, _release_row.dataset_release_id, r.* FROM _task218_rows r CROSS JOIN _run_row CROSS JOIN _source_row CROSS JOIN _release_row ON CONFLICT (pipeline_run_id, territory_code, indicator_code, provider_period_code, unit_code, attribute_hash) DO UPDATE SET value=EXCLUDED.value, observation_status=EXCLUDED.observation_status, attributes=EXCLUDED.attributes, source_payload=EXCLUDED.source_payload;
INSERT INTO curated.dim_indicator (source_id, source_indicator_code, indicator_name, description, topic) SELECT DISTINCT s.source_id, indicator_code, indicator_name, 'IMF PIP source-scoped scalar indicator preserving portfolio instrument and counterpart economy in indicator identity/attributes', 'External Sector / Portfolio Investment Positions' FROM _task218_rows CROSS JOIN _source_row s ON CONFLICT (source_id, source_indicator_code) DO UPDATE SET indicator_name=EXCLUDED.indicator_name, description=EXCLUDED.description, topic=EXCLUDED.topic;
INSERT INTO curated.dim_unit (unit_code, unit_name, unit_description) SELECT DISTINCT unit_code, unit_label, 'IMF PIP USD unit with provider scale preserved' FROM _task218_rows ON CONFLICT (unit_code) DO UPDATE SET unit_name=EXCLUDED.unit_name, unit_description=EXCLUDED.unit_description;
INSERT INTO curated.dim_period (frequency, period_year, period_start_date, period_end_date, period_label) SELECT DISTINCT 'A', period_year, make_date(period_year,1,1), make_date(period_year,12,31), provider_period_code FROM _task218_rows ON CONFLICT (frequency, period_start_date, period_end_date) DO UPDATE SET period_year=EXCLUDED.period_year, period_label=EXCLUDED.period_label;
INSERT INTO curated.dim_attribute_set (attribute_hash, attributes) SELECT DISTINCT attribute_hash, attributes FROM _task218_rows ON CONFLICT (attribute_hash) DO UPDATE SET attributes=EXCLUDED.attributes;
INSERT INTO curated.fact_observation (source_id, dataset_release_id, pipeline_run_id, indicator_id, territory_id, period_id, unit_id, attribute_set_id, value, as_of_date, observation_status) SELECT s.source_id, rel.dataset_release_id, pr.pipeline_run_id, i.indicator_id, t.territory_id, p.period_id, u.unit_id, a.attribute_set_id, r.value, '2026-03-11'::date, CASE WHEN r.observation_status='missing' THEN 'missing' ELSE 'observed' END FROM _task218_rows r CROSS JOIN _source_row s CROSS JOIN _release_row rel CROSS JOIN _run_row pr JOIN curated.dim_indicator i ON i.source_id=s.source_id AND i.source_indicator_code=r.indicator_code JOIN curated.dim_territory t ON t.iso3_code=r.territory_code JOIN curated.dim_period p ON p.period_year=r.period_year AND p.frequency='A' JOIN curated.dim_unit u ON u.unit_code=r.unit_code JOIN curated.dim_attribute_set a ON a.attribute_hash=r.attribute_hash ON CONFLICT (source_id, indicator_id, territory_id, period_id, unit_id, attribute_set_id, as_of_date) DO UPDATE SET value=EXCLUDED.value, observation_status=EXCLUDED.observation_status, dataset_release_id=EXCLUDED.dataset_release_id, pipeline_run_id=EXCLUDED.pipeline_run_id;
INSERT INTO meta.lineage_event (pipeline_run_id, source_id, event_type, from_artifact, to_artifact, checksum_sha256, row_count, details) SELECT r.pipeline_run_id, s.source_id, 'task218_imf_pip_portfolio_counterpart_loaded', 'data/raw/task218_imf_pip_phase2_campaign/active', 'data/processed/task218_imf_pip_phase2_campaign/active/task-218-imf-pip-normalized.json', '2a6a130ec8c0a45d43f0a15c57bdd52c637cdc2fe4b740c8cd88260d1f30281b', (SELECT count(*) FROM _task218_rows), '{"candidate_cell_count": 8640, "explicit_missing_value_count": 275, "observed_value_count": 8000, "release_as_of_date": "2026-03-11", "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-218", "whole_series_absence_count": 73}'::jsonb FROM _run_row r CROSS JOIN _source_row s;
INSERT INTO meta.quality_check (pipeline_run_id, check_name, check_status, observed_value, expected_value, details) SELECT pipeline_run_id, 'task218_candidate_reconciliation', CASE WHEN (SELECT count(*) FROM _task218_rows)=8275 THEN 'pass' ELSE 'fail' END, (SELECT count(*) FROM _task218_rows), 8275, '{"candidate_cell_count": 8640, "explicit_missing_value_count": 275, "observed_value_count": 8000, "release_as_of_date": "2026-03-11", "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-218", "whole_series_absence_count": 73}'::jsonb FROM _run_row UNION ALL SELECT pipeline_run_id, 'task218_observed_missing_reconciliation', CASE WHEN (SELECT count(*) FILTER (WHERE observation_status='observed') FROM _task218_rows)=8000 AND (SELECT count(*) FILTER (WHERE observation_status='missing') FROM _task218_rows)=275 THEN 'pass' ELSE 'fail' END, (SELECT count(*) FROM _task218_rows), 8275, '{"candidate_cell_count": 8640, "explicit_missing_value_count": 275, "observed_value_count": 8000, "release_as_of_date": "2026-03-11", "release_identity_basis": "provider dataset UPDATE_DATE/PUBLICATION_DATE/Prepared evidence", "task": "TASK-218", "whole_series_absence_count": 73}'::jsonb FROM _run_row;
