
BEGIN;
CREATE TABLE IF NOT EXISTS staging.task218_imf_pip_portfolio_counterpart_observation (observation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pipeline_run_id uuid NOT NULL REFERENCES meta.pipeline_run(pipeline_run_id), source_id uuid NOT NULL REFERENCES meta.source(source_id), dataset_release_id uuid REFERENCES meta.dataset_release(dataset_release_id), territory_code text NOT NULL, territory_label text NOT NULL, indicator_code text NOT NULL, indicator_name text NOT NULL, provider_period_code text NOT NULL, period_year integer NOT NULL, value numeric, unit_code text NOT NULL, unit_label text NOT NULL, decimal_precision integer, observation_status text NOT NULL, attribute_hash text NOT NULL, attributes jsonb NOT NULL, source_payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT uq_staging_task218_imf_pip_natural UNIQUE (pipeline_run_id, territory_code, indicator_code, provider_period_code, unit_code, attribute_hash));
CREATE TEMP TABLE _task218_rows (territory_code text, territory_label text, indicator_code text, indicator_name text, provider_period_code text, period_year integer, value numeric, unit_code text, unit_label text, decimal_precision integer, observation_status text, attribute_hash text, attributes jsonb, source_payload jsonb) ON COMMIT DROP;
CREATE TEMP TABLE _source_row (source_id uuid) ON COMMIT DROP; CREATE TEMP TABLE _release_row (dataset_release_id uuid) ON COMMIT DROP; CREATE TEMP TABLE _run_row (pipeline_run_id uuid) ON COMMIT DROP;
DELETE FROM curated.fact_observation f USING _source_row s, _run_row pr WHERE f.source_id=s.source_id AND f.pipeline_run_id=pr.pipeline_run_id;
COMMIT;
